// ─────────────────────────────────────────────────────────────
//  INBOX INTELLIGENCE · CONFIG — the only node you should need to edit
// ─────────────────────────────────────────────────────────────
const cfg = {
  // Who the inbox belongs to (used in every judgment and to tell your messages from everyone else's)
  owner: {
    name: 'Stan',
    role: 'Senior AI architect and advisor to C-suite and executive leadership',
    focus: ['AI strategy', 'automation', 'agentic systems', 'digital transformation', 'executive advisory'],
  },
  ownerEmails: ['you@YOUR-DOMAIN.com'], // every address you send from (aliases too), lower-case
  reportTo: ['you@YOUR-DOMAIN.com'], // weekly report recipients
  timezone: 'Europe/London',
  gmailAccountIndex: 0, // the /u/N/ in your Gmail URL, for links in the report

  // Known relationships — exact lookups stay in code; the model is told the fact, not asked to guess it.
  // Entries are domains (acme.com) or full addresses (jane@acme.com).
  relationships: {
    client: [],
    prospect: [],
    partner: [],
    team: [],
  },

  // Safety switches
  applyLabels: true, // false = judge and report only, never touch Gmail labels
  archiveLowValueBulk: false, // true = low-value newsletters/promotions also leave the inbox (still searchable)
  sortEnabled: true, // false = the 2-hourly sort does nothing (weekly report still runs)

  // Scope
  sortQuery: 'in:inbox newer_than:2d -in:chats', // what the 2-hourly sort looks at
  reportQuery: 'newer_than:7d -in:chats -in:spam -in:trash -in:draft', // what the weekly report reads
  maxThreadsPerRun: 400, // hard cap on threads judged per run (cost guardrail)
  maxMessagesPerThread: 4, // latest N messages of each thread are sent for judgment
  maxCharsPerMessage: 1200,
  lookBackDays: 7,
  lookAheadDays: 7,
  eventsPerRequest: 12, // calendar events judged per TypeSafe request

  // Decision policy — thresholds on TypeSafe probabilities / scores. Tune on your own mail.
  thresholds: {
    action: 0.6, // P(you owe a reply/decision/deliverable)
    waiting: 0.6, // P(you are waiting on someone else)
    commitment: 0.6, // P(you promised something not yet done)
    risk: 0.5, // P(dissatisfaction / escalation / relationship risk)
    reading: 1.8, // bulk relevance score (0–3) that earns "Worth reading"
    minCategoryConfidence: 0.55, // below this the thread also gets the Review label
    nudgeAfterDays: 3, // "waiting on" items older than this are flagged to chase
  },
  // Priority = weighted blend of judgments (0–100). Change weights without re-running any judgment.
  weights: { urgency: 30, value: 30, action: 15, risk: 15, deadlineSoon: 10 },

  // Labels (Gmail nests anything after "/")
  labels: {
    root: 'IQ',
    action: 'IQ/1-Action',
    waiting: 'IQ/2-Waiting On',
    commitment: 'IQ/3-My Commitments',
    risk: 'IQ/Risk',
    review: 'IQ/Review',
    reading: 'IQ/Reading',
    lowValue: 'IQ/Low Value',
    category: {
      client_delivery: 'IQ/Client',
      new_business: 'IQ/New Business',
      partnerships_speaking: 'IQ/Partnerships',
      finance_admin: 'IQ/Finance-Admin',
      team_ops: 'IQ/Team-Ops',
      personal: 'IQ/Personal',
      automated_notification: 'IQ/Notifications',
      other: 'IQ/Other',
    },
  },

  // APIs
  typesafeApi: 'https://api.typesafe.ai',
  typesafeModel: 'jev-latest',
  gmailApi: 'https://gmail.googleapis.com/gmail/v1/users/me',
  calendarApi: 'https://www.googleapis.com/calendar/v3/calendars/primary',
};

cfg.allLabels = [
  cfg.labels.root, cfg.labels.action, cfg.labels.waiting, cfg.labels.commitment, cfg.labels.risk,
  cfg.labels.review, cfg.labels.reading, cfg.labels.lowValue, ...Object.values(cfg.labels.category),
];

return $input.all().map((item) => ({ json: { ...item.json, cfg } }));

// ── shared helpers: core ─────────────────────────────
const CFG = $('Config').first().json.cfg;
const ROUTE = $('Config').first().json.route;
const NOW = new Date();
const HOUR = 3600000;
const DAY = 86400000;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const lower = (s) => String(s || '').trim().toLowerCase();
const OWNER_EMAILS = CFG.ownerEmails.map(lower);
const isOwner = (email) => OWNER_EMAILS.includes(lower(email));

// "Jane Doe" <jane@acme.com>, jane@acme.com, "Doe, Jane" <jane@acme.com>
function parseAddressList(h) {
  const out = [];
  const re = /(?:"?([^"<,]*(?:,[^"<,]*)?)"?\s*)?<([^>]+)>|([^\s,<>"]+@[^\s,<>"]+)/g;
  let m;
  while ((m = re.exec(String(h || '')))) {
    const email = lower(m[2] || m[3]);
    const name = String(m[1] || '').replace(/^[\s,]+|[\s,]+$/g, '').trim();
    if (email.includes('@')) out.push({ name: name || email.split('@')[0], email });
  }
  return out;
}

const header = (msg, name) =>
  ((msg.payload || {}).headers || []).find((h) => lower(h.name) === lower(name))?.value || '';

function relationshipOf(email) {
  const e = lower(email);
  const domain = e.split('@')[1] || '';
  for (const [kind, list] of Object.entries(CFG.relationships || {})) {
    if ((list || []).some((x) => lower(x) === e || lower(x) === domain)) return kind;
  }
  return null;
}

// Calendar dates in the owner's timezone
const dayKey = (d) => new Date(d).toLocaleDateString('en-CA', { timeZone: CFG.timezone }); // YYYY-MM-DD
const fmtDay = (d) => new Date(d).toLocaleDateString('en-GB', { timeZone: CFG.timezone, weekday: 'short', day: 'numeric', month: 'short' });
const fmtLongDay = (d) => new Date(d).toLocaleDateString('en-GB', { timeZone: CFG.timezone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const fmtTime = (d) => new Date(d).toLocaleTimeString('en-GB', { timeZone: CFG.timezone, hour: '2-digit', minute: '2-digit' });
const daysBetween = (a, b) => Math.round((Date.parse(`${dayKey(b)}T00:00:00Z`) - Date.parse(`${dayKey(a)}T00:00:00Z`)) / DAY);
const gmailLink = (threadId) => `https://mail.google.com/mail/u/${CFG.gmailAccountIndex}/#all/${threadId}`;
// ── end core ─────────────────────────────────────────
// One item per thread from the paginated threads.list responses (capped). Always emits at least one item
// so an empty inbox still reaches the weekly report: { none: true } is routed past the judging steps.
const seen = new Set();
const ids = [];
for (const page of $input.all()) {
  for (const t of page.json.threads || []) {
    if (!seen.has(t.id)) {
      seen.add(t.id);
      ids.push(t.id);
    }
  }
}
const kept = ids.slice(0, CFG.maxThreadsPerRun);
if (!kept.length) return [{ json: { none: true } }];
return kept.map((threadId) => ({ json: { threadId, truncated: ids.length > kept.length ? ids.length - kept.length : 0 } }));

// ── shared helpers: core ─────────────────────────────
const CFG = $('Config').first().json.cfg;
const ROUTE = $('Config').first().json.route;
const NOW = new Date();
const HOUR = 3600000;
const DAY = 86400000;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const lower = (s) => String(s || '').trim().toLowerCase();
const OWNER_EMAILS = CFG.ownerEmails.map(lower);
const isOwner = (email) => OWNER_EMAILS.includes(lower(email));

// "Jane Doe" <jane@acme.com>, jane@acme.com, "Doe, Jane" <jane@acme.com>
function parseAddressList(h) {
  const out = [];
  const re = /(?:"?([^"<,]*(?:,[^"<,]*)?)"?\s*)?<([^>]+)>|([^\s,<>"]+@[^\s,<>"]+)/g;
  let m;
  while ((m = re.exec(String(h || '')))) {
    const email = lower(m[2] || m[3]);
    const name = String(m[1] || '').replace(/^[\s,]+|[\s,]+$/g, '').trim();
    if (email.includes('@')) out.push({ name: name || email.split('@')[0], email });
  }
  return out;
}

const header = (msg, name) =>
  ((msg.payload || {}).headers || []).find((h) => lower(h.name) === lower(name))?.value || '';

function relationshipOf(email) {
  const e = lower(email);
  const domain = e.split('@')[1] || '';
  for (const [kind, list] of Object.entries(CFG.relationships || {})) {
    if ((list || []).some((x) => lower(x) === e || lower(x) === domain)) return kind;
  }
  return null;
}

// Calendar dates in the owner's timezone
const dayKey = (d) => new Date(d).toLocaleDateString('en-CA', { timeZone: CFG.timezone }); // YYYY-MM-DD
const fmtDay = (d) => new Date(d).toLocaleDateString('en-GB', { timeZone: CFG.timezone, weekday: 'short', day: 'numeric', month: 'short' });
const fmtLongDay = (d) => new Date(d).toLocaleDateString('en-GB', { timeZone: CFG.timezone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const fmtTime = (d) => new Date(d).toLocaleTimeString('en-GB', { timeZone: CFG.timezone, hour: '2-digit', minute: '2-digit' });
const daysBetween = (a, b) => Math.round((Date.parse(`${dayKey(b)}T00:00:00Z`) - Date.parse(`${dayKey(a)}T00:00:00Z`)) / DAY);
const gmailLink = (threadId) => `https://mail.google.com/mail/u/${CFG.gmailAccountIndex}/#all/${threadId}`;
// ── end core ─────────────────────────────────────────
// ── shared helpers: mail ─────────────────────────────
// Gmail message → plain text, bulk-mail detection and date candidates.

const decodeB64 = (data) => Buffer.from(String(data || '').replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');

function findPart(part, mime) {
  if (!part) return null;
  if (part.mimeType === mime && part.body && part.body.data) return part.body.data;
  for (const p of part.parts || []) {
    const hit = findPart(p, mime);
    if (hit) return hit;
  }
  return null;
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'");
}

// Drops quoted history so each message contributes only what it adds.
function stripQuoted(text) {
  const cut = String(text).search(/^\s*(On .{5,200}wrote:|-{2,}\s*Original Message|_{5,}\s*$|From: .+\n(Sent|Date): )/im);
  const kept = cut > 0 ? text.slice(0, cut) : text;
  return kept.split('\n').filter((l) => !/^\s*>/.test(l)).join('\n').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function messageText(msg) {
  const plain = findPart(msg.payload, 'text/plain');
  const html = plain ? null : findPart(msg.payload, 'text/html');
  const raw = plain ? decodeB64(plain) : html ? htmlToText(decodeB64(html)) : msg.snippet || '';
  const text = stripQuoted(raw) || String(msg.snippet || '');
  return text.length > CFG.maxCharsPerMessage ? `${text.slice(0, CFG.maxCharsPerMessage)}…` : text;
}

const BULK_CATEGORIES = ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'CATEGORY_FORUMS', 'CATEGORY_UPDATES'];
const BULK_SENDER = /^(no-?reply|do-?not-?reply|notifications?|notify|mailer-daemon|updates?|news(letter)?|marketing|info|hello|team)@/i;

// Bulk = you never wrote in the thread AND it carries a mailing-list/marketing signal. Rule-based on purpose:
// Gmail headers state this as fact, so no judgment is spent on it.
function isBulkThread(messages, ownerWrote) {
  if (ownerWrote) return false;
  return messages.some((m) =>
    header(m, 'List-Unsubscribe') ||
    /^(bulk|list|junk)$/i.test(header(m, 'Precedence').trim()) ||
    (m.labelIds || []).some((l) => BULK_CATEGORIES.includes(l)) ||
    BULK_SENDER.test((parseAddressList(header(m, 'From'))[0] || {}).email || ''));
}

// ── Date candidates: code finds and resolves date phrases; the model only picks which (if any) is a deadline ──
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const WEEKDAYS = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
const addDays = (key, n) => {
  const d = new Date(`${key}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const weekdayOf = (key) => new Date(`${key}T00:00:00Z`).getUTCDay();
const mondayOf = (key) => addDays(key, -((weekdayOf(key) + 6) % 7));
const validYmd = (y, m, d) => {
  const dt = new Date(Date.UTC(y, m, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m && dt.getUTCDate() === d ? dt.toISOString().slice(0, 10) : null;
};

function findDateCandidates(text, refDate) {
  const ref = dayKey(refDate);
  const found = [];
  const add = (date, m) => {
    if (!date) return;
    const ctx = text.slice(Math.max(0, m.index - 90), m.index + m[0].length + 60).replace(/\s+/g, ' ').trim();
    found.push({ date, phrase: m[0].trim(), context: ctx });
  };
  const each = (re, fn) => {
    for (const m of text.matchAll(re)) add(fn(m), m);
  };
  const nextWeekday = (wd, strictlyAfter = true) => {
    let k = addDays(ref, strictlyAfter ? 1 : 0);
    while (weekdayOf(k) !== wd) k = addDays(k, 1);
    return k;
  };

  each(/\b(today|tonight|end of (?:the )?day|EOD|COB)\b/gi, () => ref);
  each(/\btomorrow\b/gi, () => addDays(ref, 1));
  each(/\b(end of (?:the )?week|EOW)\b/gi, () => nextWeekday(5, false));
  each(/\bnext week\b/gi, () => nextWeekday(1));
  each(/\b(end of (?:the )?month|EOM)\b/gi, () => {
    const [y, mo] = ref.split('-').map(Number);
    return new Date(Date.UTC(y, mo, 0)).toISOString().slice(0, 10);
  });
  each(/\b(?:(next|this)\s+)?(monday|tuesday|wednesday|thursday|friday|saturday|sunday|mon|tues?|wed|thurs?|fri)\b\.?/gi, (m) => {
    const wd = WEEKDAYS[m[2].slice(0, 3).toLowerCase()];
    let k = nextWeekday(wd);
    // "next Friday" said early in a week means the Friday after this one
    if (/next/i.test(m[1] || '') && mondayOf(k) === mondayOf(ref)) k = addDays(k, 7);
    return k;
  });
  const monthIdx = (s) => MONTHS.indexOf(s.slice(0, 3).toLowerCase());
  const withYear = (y, mo, d) => {
    if (y) return validYmd(Number(y), mo, d);
    const refYear = Number(ref.slice(0, 4));
    const k = validYmd(refYear, mo, d);
    return k && k < addDays(ref, -30) ? validYmd(refYear + 1, mo, d) : k;
  };
  const MON = '(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
  each(new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?${MON}\\.?(?:,?\\s+(20\\d\\d))?\\b`, 'gi'), (m) => withYear(m[3], monthIdx(m[2]), Number(m[1])));
  each(new RegExp(`\\b${MON}\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(20\\d\\d))?\\b`, 'gi'), (m) => withYear(m[3], monthIdx(m[1]), Number(m[2])));
  each(/\b(20\d\d)-(\d\d)-(\d\d)\b/g, (m) => validYmd(Number(m[1]), Number(m[2]) - 1, Number(m[3])));

  return found;
}
// ── end mail ─────────────────────────────────────────
// ── rubric.json (edit the file, then npm run build) ──
const RUBRIC = {"useCase":"inbox-intelligence","version":"1.0.0","model":"jev-latest","about":"The judgments Jev answers for the inbox brief. Code supplies the state and owns the policy (thresholds, weights, labels). Placeholders: {{owner}}, {{role}}, {{i}} (event index in state.events).","groups":{"thread":{"state":"{ owner: {name, role}, today, thread: { subject, counterpart: {name, email, known_relationship}, other_participants[], message_count, last_message_from_owner, days_since_last_message, recent_messages: [{from, sent, text}] } }","questions":{"category":{"type":"choice","instructions":"Which area of {{owner}}'s work is `thread` mainly about? {{owner}} is the owner of this inbox.","criteria":{"client_delivery":"Work for an existing client: engagements, deliverables, workshops, feedback, scheduling client sessions","new_business":"Winning new work: enquiries, prospects, proposals, pricing, introductions to potential clients","partnerships_speaking":"Partnerships, collaborations, speaking, media, podcasts, advisory boards, community","finance_admin":"Invoices, payments, contracts, legal, tax, insurance, accounts, suppliers","team_ops":"Running {{owner}}'s own business: associates, contractors, tools, internal planning","personal":"Personal or family matters unrelated to work","automated_notification":"Machine-generated message from a system or service, with no person expecting a reply","other":"None of the above"}},"needs_owner_action":{"type":"noul","instructions":"Considering the whole of `thread`, is someone waiting on {{owner}} (the owner) for a reply, decision, approval, information or deliverable that the thread does not show {{owner}} has already given?","criteria":{"true":"Yes: a question, request or proposal is addressed to {{owner}} and is still unanswered or undelivered","false":"No: nothing is outstanding from {{owner}}; the thread is informational, already answered, or closed with thanks"}},"awaiting_others":{"type":"noul","instructions":"Considering the whole of `thread`, is {{owner}} (the owner) waiting on someone else for a reply, decision, document or action that has not yet arrived in the thread?"},"owner_commitment_open":{"type":"noul","instructions":"Did {{owner}} (the owner) personally commit in `thread` to do something (send, review, introduce, call, deliver) that later messages do not show as done?"},"relationship_risk":{"type":"noul","instructions":"Does `thread` show a risk to {{owner}}'s relationship with the other party: dissatisfaction, complaint, escalation, frustration at slow response, a dispute, or a threat to cancel?"},"urgency":{"type":"score","instructions":"How time-critical is `thread` for {{owner}} as of `today`?","criteria":["No time pressure: informational, or no action needed","Weeks: something to handle this month","This week: needs handling within the next few working days","Immediate: due within 48 hours, overdue, or explicitly marked urgent"]},"strategic_value":{"type":"score","instructions":"How much does `thread` matter to {{owner}}'s business, given their role as {{role}}?","criteria":["None: no business relevance","Routine: ordinary operations or logistics","Significant: active client work, revenue, or a relationship that matters","Material: new revenue opportunity, senior executive stakeholder, or contractual, financial or reputational stakes"]},"deadline":{"type":"choice","optional":"Asked only when code found date phrases; code adds one option per candidate (d1…d6) before `none`.","instructions":"Each option is a date mentioned in `thread`, already resolved to a calendar date. Which one is a deadline or scheduled commitment that {{owner}} (the owner) must act on or attend? A date that is only background, in the past, or someone else's commitment is not.","criteria":{"none":"None of these is a deadline or commitment for {{owner}}"}}}},"bulk":{"state":"{ reader: {name, role, focus_areas[]}, email: {from, subject, text} }","questions":{"kind":{"type":"choice","instructions":"What kind of automated or bulk email is `email`?","criteria":{"newsletter_research":"Editorial newsletter, research digest, analysis or industry news","event_invitation":"Invitation to a conference, webinar, meetup or other event","marketing_promo":"Product marketing, promotion, sale or sales outreach sent in bulk","product_notification":"Automated notice from a tool or service: activity, alerts, reminders, digests of app activity","billing_receipt":"Invoice, receipt, payment, subscription or billing notice","security_account":"Security alert, sign-in notice, password or account change","other":"None of the above"}},"relevance":{"type":"score","instructions":"How useful is `email` to `reader`, given their role and `reader.focus_areas`?","criteria":["No use: unrelated to their work or interests, or pure promotion","Marginal: loosely related; safe to skip","Useful: substantive content on one of their focus areas worth a skim this week","High value: insight, data, opportunity or event directly relevant to their advisory work that they would regret missing"]}}},"event":{"state":"{ owner: {name, role}, today, events: [{ title, when, attendees[], known_relationship, description, open_email_threads[] }] }","perItem":"Question names are prefixed e{{i}}_ ; `prep` is asked only for upcoming events.","questions":{"type":{"type":"choice","instructions":"What kind of meeting is `events[{{i}}]` for {{owner}}?","criteria":{"client":"Working session, review or check-in with an existing client","new_business":"Sales conversation, discovery call, pitch or proposal meeting with a prospective client","partner_network":"Partner, collaborator, speaking, media, investor or networking meeting","internal":"Internal: {{owner}}'s own associates, contractors or suppliers","personal":"Personal appointment unrelated to work","other":"None of the above"}},"prep":{"type":"score","instructions":"How much preparation does {{owner}} need before `events[{{i}}]`? Consider its purpose, attendees and `events[{{i}}].open_email_threads`.","criteria":["None: routine or recurring; walk in as is","Light: skim notes or the latest thread beforehand","Moderate: review materials, decide positions, or resolve an open email thread first","Substantial: a deck, proposal, analysis or decision must be ready; senior or high-stakes audience"]}}}}};
// ── shared helpers: rubric ─────────────────────────────
// Questions come from rubric.json (inlined at build time as RUBRIC). Same fill rules as jev/rubric.mjs.
const fillRubric = (v, vars) =>
  typeof v === 'string' ? v.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in vars ? String(vars[k]) : m))
    : Array.isArray(v) ? v.map((x) => fillRubric(x, vars))
      : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, fillRubric(x, vars)])) : v;
const rubricQuestions = (group, vars, names) =>
  Object.fromEntries(Object.entries(RUBRIC.groups[group].questions)
    .filter(([n]) => !names || names.includes(n))
    .map(([n, q]) => {
      const { optional, ...api } = q;
      return [n, fillRubric(api, vars)];
    }));
// ── end rubric ─────────────────────────────────────────
// Gmail thread → TypeSafe request. Code gathers the facts (who wrote last, known relationships, date
// candidates); TypeSafe answers only the questions that need judgment. All questions go in ONE request per
// thread: they are independent, run in parallel, and code later consumes the ones that apply.
const O = CFG.owner.name;
const vars = { owner: O, role: CFG.owner.role };
const store = $getWorkflowStaticData('global');
store.judged = store.judged || {};
const today = dayKey(NOW);
const out = [];

for (const item of $input.all()) {
  const t = item.json;
  const messages = (t.messages || [])
    .filter((m) => !(m.labelIds || []).some((l) => ['DRAFT', 'SPAM', 'TRASH'].includes(l)))
    .sort((a, b) => Number(a.internalDate) - Number(b.internalDate));
  if (!messages.length) continue;

  const last = messages[messages.length - 1];
  // The 2-hourly sort skips threads with nothing new since they were last judged; the weekly report re-reads everything.
  if (ROUTE === 'sort' && store.judged[t.id] && store.judged[t.id].m === last.id) continue;

  const participants = new Map();
  for (const m of messages) {
    for (const h of ['From', 'To', 'Cc']) {
      for (const a of parseAddressList(header(m, h))) if (!participants.has(a.email)) participants.set(a.email, a);
    }
  }
  const fromOf = (m) => parseAddressList(header(m, 'From'))[0] || { name: 'unknown', email: '' };
  const ownerWrote = messages.some((m) => isOwner(fromOf(m).email) || (m.labelIds || []).includes('SENT'));
  const lastFromOwner = isOwner(fromOf(last).email) || (last.labelIds || []).includes('SENT');
  const others = [...participants.values()].filter((p) => !isOwner(p.email));
  const counterpart = others.find((p) => p.email === fromOf(last).email) || [...messages].reverse().map(fromOf).find((p) => !isOwner(p.email)) || others[0] || { name: '—', email: '' };
  const subject = header(messages[0], 'Subject') || '(no subject)';
  const lastAt = new Date(Number(last.internalDate));
  const bulk = isBulkThread(messages, ownerWrote);
  const recent = messages.slice(-CFG.maxMessagesPerThread);
  const texts = recent.map((m) => ({ m, text: messageText(m) }));

  const base = {
    threadId: t.id,
    lastMessageId: last.id,
    subject,
    counterpart,
    participants: others.map((p) => p.email),
    relationship: relationshipOf(counterpart.email),
    lastMessageAt: lastAt.toISOString(),
    firstMessageAt: new Date(Number(messages[0].internalDate)).toISOString(),
    lastFromOwner,
    ownerWrote,
    messageCount: messages.length,
    inInbox: messages.some((m) => (m.labelIds || []).includes('INBOX')),
    unread: messages.some((m) => (m.labelIds || []).includes('UNREAD')),
    kind: bulk ? 'bulk' : 'conversation',
    candidates: [],
  };

  if (bulk) {
    const text = texts[texts.length - 1].text;
    out.push({ json: { ...base, request: {
      model: CFG.typesafeModel,
      state: {
        reader: { name: O, role: CFG.owner.role, focus_areas: CFG.owner.focus },
        email: { from: `${counterpart.name} <${counterpart.email}>`, subject, text },
      },
      questions: rubricQuestions('bulk', vars),
    } } });
    continue;
  }

  // Deadline candidates: phrases found and resolved to dates by code, limited to the next 60 days.
  const seenDates = new Set();
  const candidates = [];
  for (const { m, text } of texts) {
    for (const c of findDateCandidates(text, new Date(Number(m.internalDate)))) {
      if (c.date < today || c.date > addDays(today, 60) || seenDates.has(c.date)) continue;
      seenDates.add(c.date);
      candidates.push({ key: `d${candidates.length + 1}`, ...c, from: isOwner(fromOf(m).email) ? O : fromOf(m).name });
    }
  }
  candidates.splice(6);

  const state = {
    owner: { name: O, role: CFG.owner.role },
    today: fmtLongDay(NOW),
    thread: {
      subject,
      counterpart: { name: counterpart.name, email: counterpart.email, known_relationship: base.relationship || 'unknown' },
      other_participants: others.filter((p) => p.email !== counterpart.email).slice(0, 8).map((p) => `${p.name} <${p.email}>`),
      message_count: messages.length,
      last_message_from_owner: lastFromOwner,
      days_since_last_message: Math.max(0, daysBetween(lastAt, NOW)),
      recent_messages: texts.map(({ m, text }) => ({
        from: isOwner(fromOf(m).email) ? `${O} (owner)` : `${fromOf(m).name} <${fromOf(m).email}>`,
        sent: fmtDay(Number(m.internalDate)),
        text,
      })),
    },
  };

  const questions = rubricQuestions('thread', vars, ['category', 'needs_owner_action', 'awaiting_others', 'owner_commitment_open', 'relationship_risk', 'urgency', 'strategic_value']);

  if (candidates.length) {
    const { deadline } = rubricQuestions('thread', vars, ['deadline']);
    deadline.criteria = {
      ...Object.fromEntries(candidates.map((c) => [c.key, `"${c.phrase}" → ${fmtLongDay(`${c.date}T12:00:00Z`)} (written by ${c.from}; context: "${c.context}")`])),
      ...deadline.criteria,
    };
    questions.deadline = deadline;
  }

  out.push({ json: { ...base, candidates, request: { model: CFG.typesafeModel, state, questions } } });
}

// The weekly report must still go out when nothing needs judging.
if (!out.length && ROUTE === 'report') return [{ json: { none: true } }];
return out;

