// "Jane Doe" <jane@acme.com>, jane@acme.com, "Doe, Jane" <jane@acme.com>
function parseAddressList(h) {
  const out = [];
  const re = /(?:"?([^"<,]*(?:,[^"<,]*)?)"?\s*)?<([^>]+)>|([^\s,<>"]+@[^\s,<>"]+)/g;
  let m;
  while ((m = re.exec(String(h || '')))) {
